// Browser talks to your BFF; BFF holds refresh token in HttpOnly cookie
app.MapPost("/bff/refresh", async (HttpContext ctx, ITokenClient tokens) =>
{
    var refresh = ctx.Request.Cookies["refresh_token"];
    if (string.IsNullOrEmpty(refresh)) return Results.Unauthorized();

    var pair = await tokens.RefreshAsync(refresh);
    ctx.Response.Cookies.Append("refresh_token", pair.RefreshToken,
        new CookieOptions { HttpOnly = true, Secure = true, SameSite = SameSiteMode.Strict });
    return Results.Json(new { access_token = pair.AccessToken });
});
// Resource API only validates short-lived access JWT — never accepts refresh token

options.Events = new JwtBearerEvents
{
    OnAuthenticationFailed = ctx =>
    {
        var log = ctx.HttpContext.RequestServices
            .GetRequiredService<ILoggerFactory>().CreateLogger("JwtBearer");
        log.LogWarning(ctx.Exception,
            "JWT failed Path={Path} Expired={Expired}",
            ctx.Request.Path,
            ctx.Exception is SecurityTokenExpiredException);
        return Task.CompletedTask;
    },
    OnChallenge = ctx =>
    {
        // Default 401 — add WWW-Authenticate for OAuth clients
        ctx.HandleResponse();
        ctx.Response.StatusCode = StatusCodes.Status401Unauthorized;
        return ctx.Response.WriteAsJsonAsync(new { error = "invalid_token" });
    }
};
